            "seed": sampling["seed"],
        },
        "constraints": {
            "residuals": constraint_residuals,
            "maximum_residual": max_constraint_residual,
            "finite": constraints_finite,
        },
        "planned_contrasts": contrast_results,
        "status": status,
    }


def main() -> int:
    report: dict[str, Any] = {
        "schema_version": "0.3",
        "offline": True,
        "status_contract": {
            "workflow_completed": "The candidate model produced finite posterior observations and constraint diagnostics.",
            "pre_fix_expected_failure": "The model ran, but a usable finite observation was not produced.",
            "runner_failure": "Execution failed before a usable scientific observation was available.",
        },
    }
    try:
        sys.path.insert(0, str(SOURCE_DIR))
        import numpy as np
        import pymc as pm

        result = run_workflow(pm, np, load_case())
        report["status"] = result["status"]
        report["result"] = result
    except Exception as exc:
        report["status"] = "runner_failure"
        report["error_type"] = type(exc).__name__
        report["error"] = str(exc)

    OUTPUT_DIR.mkdir(exist_ok=True)
    output_path = OUTPUT_DIR / "public_reproduction_report.json"
    output_path.write_text(
        json.dumps(report, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    print(json.dumps(report, indent=2, sort_keys=True))
    return 0 if report["status"] == "workflow_completed" else 1


if __name__ == "__main__":
    raise SystemExit(main())

